<template><div><DsPageHeader title="Grupos e classificações" subtitle="Cadastros usados nas normalidades por classificação" icon="diagram-3"/><DsPageShell><div class="grid lg:grid-cols-2 gap-6"><section><DsSectionTitle title="Grupos"/><div class="flex gap-2 mb-3"><DsInput v-model="novoGrupo" placeholder="Nome do grupo"/><DsButton @click="criarGrupo">Adicionar</DsButton></div><div v-for="g in data.grupos" :key="g.codGrupo" class="flex justify-between border-b py-2"><span>{{ g.nome }}</span><span class="flex gap-1"><DsButton size="sm" variant="secondary" @click="editarGrupo(g)">Editar</DsButton><DsButton variant="danger" size="sm" @click="excluirGrupo(g.codGrupo)">Excluir</DsButton></span></div></section><section><DsSectionTitle title="Classificações"/><div class="grid grid-cols-3 gap-2 mb-3"><DsInput v-model="nova.nome" placeholder="Nome"/><DsSelect v-model="nova.codGrupo"><option value="">Grupo</option><option v-for="g in data.grupos" :key="g.codGrupo" :value="String(g.codGrupo)">{{ g.nome }}</option></DsSelect><DsButton @click="criarClassificacao">Adicionar</DsButton></div><div v-for="c in data.classificacoes" :key="c.codClassificacao" class="flex justify-between border-b py-2"><span>{{ c.nome }} <small class="text-gray-500">({{ groupName(c.codGrupo) }})</small></span><span class="flex gap-1"><DsButton size="sm" variant="secondary" @click="editarClassificacao(c)">Editar</DsButton><DsButton variant="danger" size="sm" @click="excluirClassificacao(c.codClassificacao)">Excluir</DsButton></span></div></section></div><DsButton class="mt-5" variant="secondary" to="/variaveis">Voltar</DsButton></DsPageShell></div></template>
<script setup lang="ts">import type { Classificacao, ClassificacaoGrupo } from '~/composables/useVariaveisApi'; definePageMeta({layout:'default'}); const api=useVariaveisApi(); const swal=useSwal(); const data=ref<{grupos:ClassificacaoGrupo[];classificacoes:Classificacao[]}>({grupos:[],classificacoes:[]}); const novoGrupo=ref(''); const nova=reactive({nome:'',codGrupo:''}); async function load(){data.value=(await api.getClassificacoes()).data} async function run(f:()=>Promise<unknown>){try{await f();await load()}catch(e){await swal.toast(e instanceof Error?e.message:'Erro','error')}} const criarGrupo=()=>run(()=>api.createGrupoClassificacao(novoGrupo.value)); const editarGrupo=(g:ClassificacaoGrupo)=>{const nome=prompt('Nome do grupo',g.nome);if(nome)run(()=>api.updateGrupoClassificacao(g.codGrupo,nome))}; const excluirGrupo=(id:number)=>run(()=>api.deleteGrupoClassificacao(id)); const criarClassificacao=()=>run(()=>api.createClassificacao({nome:nova.nome,codGrupo:Number(nova.codGrupo)})); const editarClassificacao=(c:Classificacao)=>{const nome=prompt('Nome da classificação',c.nome);if(nome)run(()=>api.updateClassificacao(c.codClassificacao,{nome,codGrupo:c.codGrupo}))}; const excluirClassificacao=(id:number)=>run(()=>api.deleteClassificacao(id)); const groupName=(id:number)=>data.value.grupos.find(g=>g.codGrupo===id)?.nome||id; onMounted(load)</script>
